add(kp,"操作系统发展的第一阶段是（）。","人工操作阶段",["批处理阶段","分时系统阶段","网络操作系统阶段"],"操作系统发展经历了人工操作、单道批处理、多道批处理、分时系统等多个阶段。")
add(kp,"单道批处理系统的特点是（）。","内存中只有一道作业，CPU等待I/O时处于空闲",["内存中有多道作业","用户可以直接与系统交互","系统响应时间很短"],"单道批处理系统中内存只有一道作业，CPU在I/O操作时空闲等待，资源利用率低。")
add(kp,"多道批处理系统引入的目的是（）。","提高CPU和I/O设备的利用率",["方便用户使用计算机","支持多用户交互","提高系统响应速度"],"多道批处理系统引入的主要目的是提高CPU和I/O设备的并行工作程度，从而提高资源利用率。")
add(kp,"多道批处理系统的特点是（）。","内存中同时存放多道作业，CPU在等待I/O时可运行其他作业",["用户可以直接与系统交互","系统立即响应用户请求","只有一道作业在内存中"],"多道批处理系统的核心特点是在内存中存放多道作业，当一道作业等待I/O时，CPU可运行另一道作业。")
add(kp,"分时系统的主要目标是（）。","及时响应多个用户的请求",["提高CPU利用率","提高系统吞吐量","减少内存使用"],"分时系统的主要目标是对多个用户的请求提供及时的交互式响应，使用户感觉独占计算机。","中等")
add(kp,"第一个分时操作系统是（）。","CTSS",["MS-DOS","UNIX","Windows"],"CTSS（Compatible Time-Sharing System）于1961年在MIT开发，是第一个分时操作系统。","中等")
