add(kp,"推动操作系统发展的主要动力不包括（）。","降低计算机硬件成本",["提高计算机系统资源利用率","方便用户使用","适应硬件体系结构发展"],"推动操作系统发展的主要动力包括提高资源利用率、方便用户使用、适应硬件发展等，降低硬件成本不是直接动力。")
add(kp,"批处理系统中，用户提交作业后（）。","无法干预作业的执行",["可以实时查看结果","可以随时修改程序","可以与系统交互"],"批处理系统中用户提交作业后无法干预作业执行，作业运行结束后才能看到结果。")
add(kp,"多道批处理系统相比于单道批处理系统的优势是（）。","系统资源利用率更高",["用户交互更方便","系统响应更快","程序编写更简单"],"多道批处理系统通过作业并发使CPU和I/O设备可以并行工作，显著提高了系统资源利用率。","中等")
add(kp,"分时系统的关键特征是（）。","交互性和及时性",["高吞吐量","自动化","无人值守"],"分时系统的关键特征是交互性（用户可与系统对话）和及时性（系统在可接受的时间内响应）。")
add(kp,"多道程序设计技术的特点不包括（）。","用户可以直接控制程序执行",["内存中存放多个程序","CPU在程序等待I/O时切换","提高了资源利用率"],"多道程序设计技术下，用户不能直接控制程序的执行，作业以批处理方式运行。")
add(kp,"以下关于分时系统的描述，错误的是（）。","分时系统对响应时间没有要求",["分时系统支持多个用户同时使用","分时系统采用时间片轮转","分时系统提供交互式使用环境"],"分时系统对响应时间有严格的要求，必须在可接受的时间（通常1-3秒）内响应用户。")
add(kp,"实时操作系统主要应用于（）。","工业控制和武器系统",["科学计算","办公自动化","游戏娱乐"],"实时操作系统主要应用于工业控制、导弹制导、医疗设备等对响应时间有严格要求的领域。","中等")
add(kp,"从人工操作到批处理系统的转变，主要解决了（）问题。","减少了CPU等待人工操作的时间",["提高了系统的交互性","增加了系统的可靠性","降低了系统的成本"],"批处理系统通过监督程序自动控制作业执行，减少了人工操作时间，提高了CPU利用率。")
add(kp,"监督程序（Monitor）是（）的雏形。","操作系统",["编译器","数据库","网络协议"],"早期的监督程序（Monitor）能够自动控制作业的装入和运行，是操作系统的雏形。","中等")
