add(kp,"分时系统的响应时间通常应控制在（）。","1-3秒",["10-30秒","1-3分钟","1-3毫秒"],"分时系统的响应时间通常应在1-3秒内，以保证用户感觉系统是在立即响应。")
add(kp,"以下关于实时系统的描述，正确的是（）。","实时系统必须在规定时间内完成事件处理",["实时系统可以允许较大的延迟","实时系统主要用于科学计算","实时系统支持大量用户交互"],"实时系统的核心特征是必须在规定的时间约束内完成对事件的处理，超时可能导致严重后果。","中等")
add(kp,"操作系统从无到有的发展历程是（）。","人工操作→单道批处理→多道批处理→分时/实时系统",["分时系统→批处理→人工操作","实时系统→分时系统→人工操作","网络系统→批处理→人工操作"],"操作系统发展的主要阶段：人工操作、单道批处理、多道批处理、分时/实时系统、通用操作系统。","中等")
add(kp,"多道批处理系统中，作业调度是指（）。","将后备队列中的作业调入内存",["将进程分配到CPU","将内存中的数据写入磁盘","将文件移动到其他目录"],"作业调度（高级调度）是指将后备队列中的作业调入内存，为其创建进程。","中等")
add(kp,"以下关于多道程序设计的描述，错误的是（）。","多道程序设计中内存只能存放一道程序",["多道程序设计中内存可存放多道程序","CPU在等待I/O时可切换到其他程序","多道程序设计提高了资源利用率"],"多道程序设计的核心是内存中同时存放多道程序，而非只能存放一道程序。")
add(kp,"分时系统的基本单位是（）。","时间片",["进程","线程","作业"],"分时系统以时间片为基本单位，每个用户轮流获得一个时间片的CPU使用权。","中等")
add(kp,"以下哪种不是操作系统的类型（）。","搜索操作系统",["批处理操作系统","分时操作系统","实时操作系统"],"搜索操作系统不是操作系统的标准分类。操作系统的标准类型包括批处理、分时和实时等。")
add(kp,"脱机批处理系统中，负责输入输出的计算机称为（）。","卫星机",["主机","服务器","终端"],"在脱机批处理系统中，负责将作业输入到磁带和从磁带输出的计算机称为卫星机（外围计算机）。")
