add(kp,"多道批处理系统的主要缺点是（）。","用户无法与作业交互",["CPU利用率低","内存容量小","不支持磁带"],"多道批处理系统的主要缺点是缺乏交互性，用户提交作业后无法在运行过程中干预。")
add(kp,"第一个广泛使用的分时操作系统UNIX诞生于（）。","1969年",["1956年","1975年","1980年"],"UNIX操作系统于1969年在AT&T贝尔实验室由Ken Thompson和Dennis Ritchie开发。","中等")
add(kp,"多道程序设计的“道”是指（）。","内存中同时存放的用户程序数量",["CPU的核数","磁盘的数量","网络带宽的大小"],"多道程序设计的“道”是指内存中同时存放的用户程序（作业）数量。")
