add(kp,"批处理系统按发展顺序分为（）。","联机批处理和脱机批处理",["脱机批处理和联机批处理","分时系统和实时系统","单用户和多用户"],"批处理系统的发展顺序为联机批处理（CPU控制I/O）再到脱机批处理（卫星机分离I/O）。","中等")
add(kp,"操作系统形成和发展的主要阶段不包括（）。","人工智能系统阶段",["人工操作阶段","单道批处理阶段","多道批处理阶段"],"操作系统发展经历了人工操作、批处理（单道/多道/脱机）、分时/实时系统、通用操作系统和网络操作系统等阶段。","中等")
add(kp,"以下关于分时系统的叙述中，正确的是（）。","分时系统的基本单位是时间片，轮转调度",["分时系统不允许用户交互","分时系统只允许一个用户使用","分时系统的响应时间为分钟级"],"分时系统以时间片为基本单位，采用轮转调度算法为每个用户轮流分配CPU时间。","中等")
add(kp,"分时系统与多道批处理系统的主要区别是（）。","分时系统强调交互性，批处理系统强调吞吐量",["两者没有区别","分时系统不支持多道程序设计","批处理系统响应更快"],"分时系统强调交互性和及时响应，而批处理系统强调系统吞吐量和CPU利用率。","中等")
add(kp,"实时操作系统可以分为（）两大类。","硬实时和软实时",["单任务和多任务","批处理和交互","网络和分布式"],"实时操作系统分为硬实时（必须严格满足时间约束）和软实时（可容忍偶尔超时）两大类。","中等")
add(kp,"操作系统的“网络操作系统”阶段，其主要功能是（）。","提供网络通信和资源共享功能",["仅提供单机文件管理","仅支持单用户操作","仅支持本地打印机"],"网络操作系统在单机操作系统基础上增加了网络通信和资源共享功能，支持多台计算机协同工作。")
add(kp,"现代操作系统的主要特征不包括（）。","只能运行在大型机上",["支持多用户多任务","支持图形用户界面","支持网络功能"],"现代操作系统可以运行在从嵌入式设备到大型机的各种硬件平台上，不限于大型机。")
add(kp,"多道批处理系统中，CPU调度是指（）。","从就绪队列中选择进程分配到CPU",["将作业从磁盘调入内存","将内存中的数据写入磁盘","创建新进程"],"CPU调度（低级调度）是指从就绪队列中选择一个进程，将CPU分配给它运行。","中等")
add(kp,"脱机批处理相比于联机批处理的改进在于（）。","使用卫星机分离I/O和计算",["增加了用户交互功能","提高了系统响应速度","减少了内存使用"],"脱机批处理的最大改进是使用卫星机（外围计算机）将I/O操作与主机计算分离，减少CPU等待时间。","中等")
add(kp,"以下关于UNIX系统的描述中，正确的是（）。","UNIX是用C语言编写的，具有良好的可移植性",["UNIX只能用汇编语言编写","UNIX不支持多用户","UNIX没有文件系统"],"UNIX采用C语言编写，具有良好的可移植性，这是其被广泛采用的重要原因。","中等")
add(kp,"推动操作系统向多道批处理系统发展的直接原因是（）。","CPU与I/O设备速度不匹配",["用户数量增加","内存容量增大","网络技术发展"],"CPU的高速与I/O设备的低速之间的速度不匹配是推动多道程序设计技术发展的直接原因。","中等")
